"""Tests for src.rb.features — _compute_features and fill_nans.

The standard "all features created", "first-week NaN", "zero-input no inf",
"multi-season independence", and ``fill_nans`` test cases are generated by
``tests.shared.parameterized_features``. RB-specific tests (temp-column
cleanup, per-rate yards/carry computation, team carry-share assertions,
all-NaN training-set fill) stay in this file.
"""

import numpy as np
import pandas as pd
import pytest

from src.rb.features import _compute_features, add_specific_features, fill_nans
from tests.rb.conftest import _build_player_games
from tests.shared.parameterized_features import (
    PositionFeatureSpec,
    install_parameterized_features,
)

FEATURE_COLS = [
    "yards_per_carry_L3",
    "reception_rate_L3",
    "team_rb_carry_share_L3",
    "team_rb_target_share_L3",
    "career_carries",
    "team_rb_carry_hhi_L3",
    "team_rb_target_hhi_L3",
    "opportunity_index_L3",
    "rushing_epa_per_attempt_L3",
    "rushing_first_down_rate_L3",
    "receiving_first_down_rate_L3",
    "yac_per_reception_L3",
    "receiving_epa_per_target_L3",
    "air_yards_per_target_L3",
]


install_parameterized_features(
    globals(),
    PositionFeatureSpec(
        position="RB",
        compute_features=_compute_features,
        fill_nans=fill_nans,
        feature_cols=FEATURE_COLS,
        make_player_games=_build_player_games,
        first_week_check_features=("yards_per_carry_L3", "reception_rate_L3"),
        zero_input_overrides={
            "carries": {"carries": 0, "rushing_yards": 0},
            "targets": {"targets": 0, "receptions": 0},
            "receptions": {"receptions": 0, "receiving_yards_after_catch": 0},
            "opportunity": {"carries": 0, "targets": 0},
        },
        zero_input_features={
            "carries": ["yards_per_carry_L3"],
            "targets": ["reception_rate_L3"],
            "receptions": ["yac_per_reception_L3"],
            "opportunity": ["opportunity_index_L3"],
        },
        seasons_check_feature="yards_per_carry_L3",
        seasons_factory_kwargs=(
            {"carries": 20, "rushing_yards": 100},
            {"carries": 5, "rushing_yards": 20},
        ),
    ),
)


@pytest.mark.unit
class TestComputeRBSpecific:
    """RB-specific tests (temp-column hygiene, per-rate computation,
    team-share arithmetic). These don't generalise to the other positions
    and stay in this file.
    """

    def test_no_temp_columns_remain(self, make_player_games):
        """Temporary columns (_raw_weighted_opps, etc.) should be cleaned up."""
        df = make_player_games()
        _compute_features(df)
        temp_cols = [c for c in df.columns if c.startswith("_")]
        assert temp_cols == [], f"Temp columns left: {temp_cols}"

    def test_zero_carries_zero_yards_per_carry(self, make_player_games):
        """Player with 0 carries: yards_per_carry_L3 should also be 0 (in addition to non-inf)."""
        df = make_player_games(n_weeks=4, carries=0, rushing_yards=0)
        _compute_features(df)
        assert (df["yards_per_carry_L3"].fillna(0) == 0).all()

    def test_yards_per_carry_computation(self, make_player_games):
        """Check yards_per_carry_L3 for constant carries/yards."""
        df = make_player_games(n_weeks=5, carries=10, rushing_yards=50)
        _compute_features(df)
        # Week 3 (index 2): shift sees weeks 1,2; rolling(3,min_periods=1) sums [50,50]=100 yds / 20 carries = 5.0
        week3 = df[df["week"] == 3]
        assert pytest.approx(week3["yards_per_carry_L3"].iloc[0], abs=0.01) == 5.0

    def test_team_carry_share_single_player(self, make_player_games):
        """Solo RB on team should have carry share of 1.0."""
        df = make_player_games(n_weeks=5, carries=15, recent_team="KC")
        _compute_features(df)
        # After enough history, share should be 1.0 (only RB on team)
        later_weeks = df[df["week"] >= 3]
        shares = later_weeks["team_rb_carry_share_L3"]
        valid = shares.dropna()
        if len(valid) > 0:
            assert (valid <= 1.01).all()  # should be ~1.0

    def test_team_carry_share_two_players(self, make_player_games):
        """Two RBs on same team split carries."""
        p1 = make_player_games("P1", n_weeks=5, carries=10, targets=3, recent_team="KC")
        p2 = make_player_games("P2", n_weeks=5, carries=10, targets=3, recent_team="KC")
        df = pd.concat([p1, p2], ignore_index=True)
        _compute_features(df)
        # Each player should have ~0.5 carry share after history builds up
        later = df[(df["week"] >= 3) & (df["player_id"] == "P1")]
        shares = later["team_rb_carry_share_L3"].dropna()
        if len(shares) > 0:
            assert all(0.4 <= s <= 0.6 for s in shares)

    def test_team_shares_stint_aware_on_trade(self, make_player_games):
        """#1193: the 3-week team-RB share denominators must reset on a
        mid-season trade, not mix the old and new team's RB volume.

        RB_A plays weeks 1-4 on KC alongside RB_B (each 10 carries / 5
        targets → KC RB totals 20 / 10 per week, share ≈ 0.5), then is traded
        to SF for weeks 5-7 where he's the lone RB (share = 1.0). At week 7
        the rolling window (shift(1) → weeks 5,6) lies entirely inside the SF
        stint, so the stint-aware share is exactly 1.0. The old
        ``player×season`` grouping spanned the trade (window weeks 4,5,6 →
        player 30 / team 20+10+10=40 = 0.75), so this value separates the fix
        from the bug — mirrors the WR test (#674).

        The HHI rollings must be stint-aware too (#1425): per-game HHI is
        0.5² + 0.5² = 0.5 in the KC weeks and 1.0 in the solo-SF weeks, so
        the stint-aware week-7 mean over window {5,6} is exactly 1.0 while
        the buggy player×season grouping averaged KC's week 4 in —
        mean(0.5, 1.0, 1.0) ≈ 0.8333.
        """
        rb_a_kc = make_player_games("RB_A", n_weeks=4, carries=10, targets=5, recent_team="KC")
        rb_a_sf = make_player_games("RB_A", n_weeks=3, carries=10, targets=5, recent_team="SF")
        rb_a_sf["week"] = [5, 6, 7]
        rb_b_kc = make_player_games("RB_B", n_weeks=4, carries=10, targets=5, recent_team="KC")
        df = pd.concat([rb_a_kc, rb_a_sf, rb_b_kc], ignore_index=True)
        _compute_features(df)

        a = df[df["player_id"] == "RB_A"].set_index("week")
        # Stint-aware: window {5,6} fully inside the SF stint → 20/20 = 1.0.
        # (A non-stint denominator would give 30/40 = 0.75, mixing KC's wk4.)
        assert pytest.approx(a.loc[7, "team_rb_carry_share_L3"], abs=1e-9) == 1.0
        assert pytest.approx(a.loc[7, "team_rb_target_share_L3"], abs=1e-9) == 1.0
        # Stint boundary (the fix's largest per-row change, old→new 0.5→0.0):
        # week 5 is the first game of the new stint, so shift(1) has no
        # prior-game inside the stint → rolling NaN → safe_divide fills 0.
        # Week 6 (window {5}) is already all-SF → 1.0. Pin both so a
        # min_periods / NaN-fill refactor can't silently move the boundary.
        assert pytest.approx(a.loc[5, "team_rb_carry_share_L3"], abs=1e-9) == 0.0
        assert pytest.approx(a.loc[6, "team_rb_carry_share_L3"], abs=1e-9) == 1.0
        # HHI rollings, stint-aware (#1425): week 7's window {5,6} is all-SF
        # → mean(1.0, 1.0) = 1.0. (The buggy player×season grouping mixed
        # KC's wk4 HHI 0.5 in → ≈0.8333.) Week 6 (window {5}) → 1.0.
        assert pytest.approx(a.loc[7, "team_rb_carry_hhi_L3"], abs=1e-9) == 1.0
        assert pytest.approx(a.loc[7, "team_rb_target_hhi_L3"], abs=1e-9) == 1.0
        assert pytest.approx(a.loc[6, "team_rb_carry_hhi_L3"], abs=1e-9) == 1.0
        assert pytest.approx(a.loc[6, "team_rb_target_hhi_L3"], abs=1e-9) == 1.0
        # Stint cold-start boundary: week 5 is the first SF game, so shift(1)
        # has no prior in-stint game → rolling NaN. Unlike the shares above
        # there is no safe_divide 0-fill on the HHI rollings, so pin NaN (the
        # downstream fill_nans train-mean fill handles it in the pipeline).
        assert np.isnan(a.loc[5, "team_rb_carry_hhi_L3"])
        assert np.isnan(a.loc[5, "team_rb_target_hhi_L3"])


@pytest.mark.unit
class TestFillRBNansSpecific:
    """RB-specific NaN-fill behaviour: all-NaN training column must emit a
    visible warning rather than silently zero (regression for the bug fixed
    in TODO.md / `fill_nans_with_train_means`)."""

    def test_all_nan_train_fills_with_zero(self, make_splits, capsys):
        """If training set is all NaN, train_mean is NaN; previously the fill
        was a silent no-op and the catch-all `.fillna(0)` in
        `build_position_features` masked the failure. The hardened
        `fill_nans_with_train_means` now substitutes 0 explicitly and prints
        a warning so the silent zero-feature is visible."""
        train, val, test = make_splits(
            [np.nan, np.nan],
            [np.nan],
            [np.nan],
        )
        train, val, test = fill_nans(train, val, test, ["feat1"])
        assert val["feat1"].iloc[0] == 0.0
        assert test["feat1"].iloc[0] == 0.0
        captured = capsys.readouterr().out
        assert "feat1" in captured
        assert "entirely NaN in training" in captured


@pytest.mark.unit
class TestFullTrainTeamTotals:
    """#574: team-total denominators (carry/target share, HHI, career) must be
    computed over the pre-MIN_GAMES-filter train so a surviving RB's share is
    measured against the FULL team — including teammates the train filter drops
    — matching what the (unfiltered) val/test splits see."""

    def test_full_train_denominator_includes_dropped_players(self, make_player_games):
        """RB_A survives the filter; RB_B (sub-min-games) is dropped from the
        filtered train but present in ``full_train``. With ``full_train`` the
        per-game carry share for RB_A is 0.5 in the weeks RB_B also played
        (10 / (10 + 10)); without it the denominator undercounts and the share
        reads 1.0."""
        # RB's min_games_per_season is 1 (PR #656), so the real filter drops
        # neither player; filtered_train selects RB_A manually below to model
        # the pipeline's post-filter frame (RB_B is the dropped teammate).
        rb_a = make_player_games("RB_A", season=2023, n_weeks=7, carries=10, recent_team="KC")
        rb_b = make_player_games("RB_B", season=2023, n_weeks=3, carries=10, recent_team="KC")
        full_train = pd.concat([rb_a, rb_b], ignore_index=True)
        # The pipeline passes the post-filter frame as train_df; build it by
        # selecting from full_train so the index labels line up (the new path
        # selects ``full_train`` rows by ``train_df.index`` membership).
        filtered_train = full_train[full_train["player_id"] == "RB_A"].copy()
        val = make_player_games("RB_A", season=2024, n_weeks=2, carries=10, recent_team="KC")
        test = make_player_games("RB_A", season=2024, n_weeks=2, carries=10, recent_team="KC")

        # New path — denominator includes RB_B for the weeks it played (1-3).
        train_new, _, _ = add_specific_features(
            filtered_train.copy(), val.copy(), test.copy(), full_train=full_train.copy()
        )
        a_new = train_new[train_new["player_id"] == "RB_A"].sort_values("week")
        assert set(a_new["week"]) == set(range(1, 8))  # all 7 surviving rows returned
        wk123 = a_new[a_new["week"].isin([1, 2, 3])]["game_carry_share"].to_numpy()
        wk4plus = a_new[a_new["week"] >= 4]["game_carry_share"].to_numpy()
        np.testing.assert_allclose(wk123, 0.5, atol=1e-9)
        np.testing.assert_allclose(wk4plus, 1.0, atol=1e-9)  # RB_B gone after wk3

        # Old path (full_train=None) — denominator is the filtered train only.
        train_old, _, _ = add_specific_features(filtered_train.copy(), val.copy(), test.copy())
        a_old = train_old[train_old["player_id"] == "RB_A"].sort_values("week")
        np.testing.assert_allclose(a_old["game_carry_share"].to_numpy(), 1.0, atol=1e-9)

    def test_full_train_none_is_back_compatible(self, make_player_games):
        """``full_train=None`` must reproduce the legacy single-frame behaviour
        exactly (the default for QB/TE/K/DST and any caller not yet threading
        the unfiltered frame)."""
        df = pd.concat(
            [
                make_player_games("P1", n_weeks=5, carries=10, targets=3, recent_team="KC"),
                make_player_games("P2", n_weeks=5, carries=10, targets=3, recent_team="KC"),
            ],
            ignore_index=True,
        )
        val = make_player_games("P1", season=2024, n_weeks=2, recent_team="KC")
        test = make_player_games("P1", season=2024, n_weeks=2, recent_team="KC")
        out_default, _, _ = add_specific_features(df.copy(), val.copy(), test.copy())
        out_none, _, _ = add_specific_features(df.copy(), val.copy(), test.copy(), full_train=None)
        pd.testing.assert_frame_equal(out_default, out_none)
